<?php $currency_symbol = $this->customlib->getSchoolCurrencyFormat(); ?>
<style>.change-fee-page .summary{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:15px}.change-fee-page .summary span{padding:8px 12px;border:1px solid #e2e7ed;border-radius:5px;background:#fff}.change-fee-page .filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:10px;margin-bottom:14px}.change-fee-page .student-name{font-weight:700;color:#26384a}.change-fee-page .student-ids{font-size:11px;color:#7a8695}.change-fee-page .month-badge{display:inline-block;min-width:105px;padding:5px 8px;border-radius:4px;background:#edf4fb;color:#315f86;text-align:center}.change-fee-page .fee-state{font-size:11px}.change-fee-page .inline-date{display:flex;gap:5px;min-width:205px}.change-fee-page .inline-date input{min-width:130px}.change-fee-page .actions{white-space:nowrap}.change-fee-page .actions form{display:inline-block}@media(max-width:767px){.change-fee-page .filters{grid-template-columns:1fr}}</style>
<div class="content-wrapper change-fee-page">
 <section class="content-header"><h1><i class="fa fa-edit"></i> Change Fee</h1><p class="text-muted">Review generated student fees by month. Amounts and fee types are locked after generation.</p></section>
 <section class="content">
  <?php if($this->session->flashdata('msg')) echo $this->session->flashdata('msg'); ?>
  <div class="nav-tabs-custom"><ul class="nav nav-tabs"><li class="active"><a href="#fees">Student Fees</a></li><?php if($this->rbac->hasPrivilege('fees_discount','can_view')){ ?><li><a href="<?php echo site_url('admin/feediscount'); ?>">Fees Discount</a></li><?php } ?></ul></div>
  <div class="summary"><span><strong><?php echo count($fee_rows); ?></strong> fee records</span><span><i class="fa fa-lock text-danger"></i> Paid/discounted records protected</span><span><i class="fa fa-calendar text-warning"></i> Due date is the only editable field</span></div>
  <div class="box box-primary"><div class="box-header"><h3 class="box-title">Generated Fee Records - <?php echo html_escape($this->setting_model->getCurrentSessionName()); ?></h3></div><div class="box-body">
   <div class="filters"><input id="fee_filter" class="form-control" placeholder="Search admission no., student, ID or fee type"><select id="month_filter" class="form-control"><option value="">All fee months</option><?php $months=array();foreach($fee_rows as $r){$key=sprintf('%04d-%02d',(int)$r['year'],(int)$r['clnd_month']);$months[$key]=date('F Y',mktime(0,0,0,(int)$r['clnd_month'],1,(int)$r['year']));}krsort($months);foreach($months as $k=>$m){ ?><option value="<?php echo $k; ?>"><?php echo html_escape($m); ?></option><?php } ?></select><select id="state_filter" class="form-control"><option value="">All statuses</option><option value="open">Unpaid / changeable</option><option value="protected">Protected</option><option value="duplicate">Legacy duplicate</option></select></div>
   <div class="table-responsive"><table class="table table-striped table-bordered" id="change_fee_table"><thead><tr><th>Student</th><th>Class</th><th>Fee Type</th><th>Fee Month</th><th class="text-right">Amount</th><th>Due Date</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody>
   <?php foreach($fee_rows as $row){$month_key=sprintf('%04d-%02d',(int)$row['year'],(int)$row['clnd_month']);$name=trim($row['firstname'].' '.$row['middlename'].' '.$row['lastname']);$state=$row['duplicate']?'duplicate':($row['protected']?'protected':'open'); ?>
    <tr data-month="<?php echo $month_key; ?>" data-state="<?php echo $state; ?>">
     <td><div class="student-name"><?php echo $name!==''?html_escape($name):'Archived student'; ?></div><div><?php echo html_escape($row['admission_no']); ?></div><div class="student-ids">Student ID <?php echo (int)$row['student_id']; ?> / Session ID <?php echo (int)$row['student_session_id']; ?> / Fee ID <?php echo (int)$row['id']; ?></div></td>
     <td><?php echo html_escape(trim($row['class'].' / '.$row['section'],' /')); ?></td><td><strong><?php echo html_escape($row['fee_type']); ?></strong><br><small><?php echo html_escape($row['fee_code']); ?></small></td>
     <td><span class="month-badge"><?php echo html_escape(date('F Y',mktime(0,0,0,(int)$row['clnd_month'],1,(int)$row['year']))); ?></span></td><td class="text-right"><strong><?php echo html_escape($currency_symbol).number_format((float)$row['amount'],2); ?></strong></td>
     <td><?php if(!$row['protected']&&!$row['duplicate']&&$this->rbac->hasPrivilege('fees_master','can_edit')){ ?><form class="inline-date" method="post" action="<?php echo site_url('admin/feemaster/changeDueDate/'.(int)$row['id']); ?>"><?php echo $this->customlib->getCSRF(); ?><input class="form-control input-sm" type="date" name="due_date" value="<?php echo html_escape($row['due_date']); ?>" required><button class="btn btn-warning btn-sm" title="Save due date"><i class="fa fa-save"></i></button></form><?php }else{ echo html_escape($row['due_date']); } ?></td>
     <td class="fee-state"><?php if($row['duplicate']){ ?><span class="label label-danger">Legacy duplicate - locked</span><?php }elseif($row['protected']){ ?><span class="label label-danger">Payment/discount applied</span><?php }else{ ?><span class="label label-success">Unpaid - amount locked</span><?php } ?></td>
     <td class="text-right actions"><?php if(!$row['protected']&&$this->rbac->hasPrivilege('fees_master','can_delete')){ ?><form method="post" action="<?php echo site_url('admin/feemaster/delete/'.(int)$row['id']); ?>" onsubmit="return confirm('Delete this unpaid fee record only? This cannot be undone.');"><?php echo $this->customlib->getCSRF(); ?><button class="btn btn-danger btn-xs" title="Delete unpaid fee"><i class="fa fa-trash"></i></button></form><?php }else{ ?><i class="fa fa-lock text-muted" title="Protected"></i><?php } ?></td>
    </tr>
   <?php } ?>
   </tbody></table></div>
  </div></div>
 </section>
</div>
<script>(function($){function filter(){var q=$.trim($('#fee_filter').val()).toLowerCase(),m=$('#month_filter').val(),s=$('#state_filter').val();$('#change_fee_table tbody tr').each(function(){var r=$(this),ok=(!q||r.text().toLowerCase().indexOf(q)>=0)&&(!m||r.data('month')===m)&&(!s||r.data('state')===s);r.toggle(ok)})}$('#fee_filter').on('input',filter);$('#month_filter,#state_filter').on('change',filter)})(jQuery);</script>
